import BlockType from '../../extension-support/block-type';
import ArgumentType from '../../extension-support/argument-type';
import Cast from '../../util/cast';
import translations from './translations.json';
import blockIcon from './block-icon.png';
import {MBotTransport} from './mbot-ble';
import {
    mbotMoveFrame,
    mbotStopFrame,
    mbotRgbLedFrame,
    mbotToneFrame,
    mbotToneOffFrame,
    mbotUltrasonicRequestFrame,
    mbotLineFollowerRequestFrame,
    mbotButtonRequestFrame,
    parseFloatResponse,
    parseButtonPressedResponse,
    calibrateUltrasonicCm,
    LINE_FOLLOWER_LEFT_MASK,
    LINE_FOLLOWER_RIGHT_MASK,
    isLineFollowerSideOnBlack,
    RGB_LED_ALL,
    RGB_LED_LEFT,
    RGB_LED_RIGHT
} from './mbot-protocol';

/**
 * Formatter which is used for translation.
 * This will be replaced which is used in the runtime.
 * @param {object} messageData - format-message object
 * @returns {string} - message for the locale
 */
let formatMessage = messageData => messageData.default;

/**
 * Setup format-message for this extension.
 */
const setupTranslations = () => {
    const localeSetup = formatMessage.setup();
    if (localeSetup && localeSetup.translations[localeSetup.locale]) {
        Object.assign(
            localeSetup.translations[localeSetup.locale],
            translations[localeSetup.locale]
        );
    }
};

const EXTENSION_ID = 'mbot';

/**
 * URL to get this extension as a module.
 * When it was loaded as a module, 'extensionURL' will be replaced a URL which is retrieved from.
 * @type {string}
 */
let extensionURL = 'https://bilgin.github.io/xcx-mbot/dist/mbot.mjs';

/**
 * Default wheel speed (0-255) for the timed move/turn blocks, matching the
 * speed code_rover_bot's Flutter app drives at.
 */
const DEFAULT_SPEED = 150;

/**
 * mBot.s2e's own defaults for these ports (Port3 for the ultrasonic sensor,
 * Port2 for the line follower) — kept as this extension's defaults too,
 * since that's where Makeblock's standard mBot kit wiring puts them.
 */
const DEFAULT_ULTRASONIC_PORT = 3;
const DEFAULT_LINE_FOLLOWER_PORT = 2;

const LED_TARGET_TO_CONSTANT = {
    all: RGB_LED_ALL,
    left: RGB_LED_LEFT,
    right: RGB_LED_RIGHT
};

const SIDE_TO_LINE_FOLLOWER_MASK = {
    left: LINE_FOLLOWER_LEFT_MASK,
    right: LINE_FOLLOWER_RIGHT_MASK
};

/**
 * Scratch 3.0 blocks to drive a Makeblock mBot over Bluetooth LE.
 */
class ExtensionBlocks {
    /**
     * A translation object which is used in this class.
     * @param {FormatObject} formatter - translation object
     */
    static set formatMessage (formatter) {
        formatMessage = formatter;
        if (formatMessage) setupTranslations();
    }

    /**
     * @return {string} - the name of this extension.
     */
    static get EXTENSION_NAME () {
        return formatMessage({
            id: 'mbot.name',
            default: 'mBot',
            description: 'name of the extension'
        });
    }

    /**
     * @return {string} - the ID of this extension.
     */
    static get EXTENSION_ID () {
        return EXTENSION_ID;
    }

    /**
     * URL to get this extension.
     * @type {string}
     */
    static get extensionURL () {
        return extensionURL;
    }

    /**
     * Set URL to get this extension.
     * The extensionURL will be changed to the URL of the loading server.
     * @param {string} url - URL
     */
    static set extensionURL (url) {
        extensionURL = url;
    }

    /**
     * Construct a set of blocks to drive an mBot.
     * @param {Runtime} runtime - the Scratch 3.0 runtime.
     */
    constructor (runtime) {
        /**
         * The Scratch 3.0 runtime.
         * @type {Runtime}
         */
        this.runtime = runtime;

        if (runtime.formatMessage) {
            // Replace 'formatMessage' to a formatter which is used in the runtime.
            formatMessage = runtime.formatMessage;
        }

        /**
         * Owns the BLE connection to the mBot.
         * @type {MBotTransport}
         */
        this.transport = new MBotTransport(runtime, ExtensionBlocks.EXTENSION_ID);
    }

    /**
     * @returns {object} metadata for this extension and its blocks.
     */
    getInfo () {
        setupTranslations();
        return {
            id: ExtensionBlocks.EXTENSION_ID,
            name: ExtensionBlocks.EXTENSION_NAME,
            extensionURL: ExtensionBlocks.extensionURL,
            blockIconURI: blockIcon,
            showStatusButton: true,
            blocks: [
                {
                    opcode: 'connect',
                    blockType: BlockType.COMMAND,
                    text: formatMessage({
                        id: 'mbot.connect',
                        default: 'connect to mBot',
                        description: 'command to start scanning for an mBot'
                    }),
                    func: 'connect'
                },
                {
                    opcode: 'disconnect',
                    blockType: BlockType.COMMAND,
                    text: formatMessage({
                        id: 'mbot.disconnect',
                        default: 'disconnect mBot',
                        description: 'command to disconnect from the mBot'
                    }),
                    func: 'disconnect'
                },
                {
                    opcode: 'isConnected',
                    blockType: BlockType.BOOLEAN,
                    text: formatMessage({
                        id: 'mbot.isConnected',
                        default: 'connected to mBot?',
                        description: 'true if connected to an mBot'
                    }),
                    func: 'isConnected'
                },
                {
                    opcode: 'lastConnectionError',
                    blockType: BlockType.REPORTER,
                    text: formatMessage({
                        id: 'mbot.lastConnectionError',
                        default: 'last mBot error',
                        description: 'the most recent BLE connection error message'
                    }),
                    func: 'lastConnectionError'
                },
                '---',
                {
                    opcode: 'move',
                    blockType: BlockType.COMMAND,
                    text: formatMessage({
                        id: 'mbot.move',
                        default: 'move [DIRECTION] at speed [SPEED] for [SECONDS] seconds',
                        description: 'command to drive both wheels for a duration'
                    }),
                    func: 'move',
                    arguments: {
                        DIRECTION: {
                            type: ArgumentType.STRING,
                            menu: 'directionMenu',
                            defaultValue: 'forward'
                        },
                        SPEED: {
                            type: ArgumentType.NUMBER,
                            defaultValue: DEFAULT_SPEED
                        },
                        SECONDS: {
                            type: ArgumentType.NUMBER,
                            defaultValue: 1
                        }
                    }
                },
                {
                    opcode: 'turn',
                    blockType: BlockType.COMMAND,
                    text: formatMessage({
                        id: 'mbot.turn',
                        default: 'turn [DIRECTION] at speed [SPEED] for [SECONDS] seconds',
                        description: 'command to spin in place for a duration'
                    }),
                    func: 'turn',
                    arguments: {
                        DIRECTION: {
                            type: ArgumentType.STRING,
                            menu: 'turnMenu',
                            defaultValue: 'left'
                        },
                        SPEED: {
                            type: ArgumentType.NUMBER,
                            defaultValue: DEFAULT_SPEED
                        },
                        SECONDS: {
                            type: ArgumentType.NUMBER,
                            defaultValue: 1
                        }
                    }
                },
                {
                    opcode: 'setMotors',
                    blockType: BlockType.COMMAND,
                    text: formatMessage({
                        id: 'mbot.setMotors',
                        default: 'set motors left [LEFT] right [RIGHT]',
                        description: 'command to set raw wheel speeds without auto-stopping'
                    }),
                    func: 'setMotors',
                    arguments: {
                        LEFT: {
                            type: ArgumentType.NUMBER,
                            defaultValue: DEFAULT_SPEED
                        },
                        RIGHT: {
                            type: ArgumentType.NUMBER,
                            defaultValue: DEFAULT_SPEED
                        }
                    }
                },
                {
                    opcode: 'stop',
                    blockType: BlockType.COMMAND,
                    text: formatMessage({
                        id: 'mbot.stop',
                        default: 'stop mBot',
                        description: 'command to stop both wheels'
                    }),
                    func: 'stop'
                },
                '---',
                {
                    opcode: 'setLed',
                    blockType: BlockType.COMMAND,
                    text: formatMessage({
                        id: 'mbot.setLed',
                        default: 'set [LED] LED to red [RED] green [GREEN] blue [BLUE]',
                        description: 'command to set the onboard RGB LED color'
                    }),
                    func: 'setLed',
                    arguments: {
                        LED: {
                            type: ArgumentType.STRING,
                            menu: 'ledMenu',
                            defaultValue: 'all'
                        },
                        RED: {
                            type: ArgumentType.NUMBER,
                            defaultValue: 255
                        },
                        GREEN: {
                            type: ArgumentType.NUMBER,
                            defaultValue: 0
                        },
                        BLUE: {
                            type: ArgumentType.NUMBER,
                            defaultValue: 0
                        }
                    }
                },
                {
                    opcode: 'playTone',
                    blockType: BlockType.COMMAND,
                    text: formatMessage({
                        id: 'mbot.playTone',
                        default: 'play tone [FREQUENCY] Hz for [DURATION] ms',
                        description: 'command to play a tone on the onboard buzzer'
                    }),
                    func: 'playTone',
                    arguments: {
                        FREQUENCY: {
                            type: ArgumentType.NUMBER,
                            defaultValue: 440
                        },
                        DURATION: {
                            type: ArgumentType.NUMBER,
                            defaultValue: 500
                        }
                    }
                },
                {
                    opcode: 'stopTone',
                    blockType: BlockType.COMMAND,
                    text: formatMessage({
                        id: 'mbot.stopTone',
                        default: 'stop tone',
                        description: 'command to stop the onboard buzzer'
                    }),
                    func: 'stopTone'
                },
                '---',
                {
                    opcode: 'ultrasonicDistance',
                    blockType: BlockType.REPORTER,
                    text: formatMessage({
                        id: 'mbot.ultrasonicDistance',
                        default: 'distance (cm) on port [PORT]',
                        description: 'reporter for the ultrasonic sensor distance reading'
                    }),
                    func: 'ultrasonicDistance',
                    arguments: {
                        PORT: {
                            type: ArgumentType.NUMBER,
                            defaultValue: DEFAULT_ULTRASONIC_PORT
                        }
                    }
                },
                {
                    opcode: 'lineFollowerValue',
                    blockType: BlockType.REPORTER,
                    text: formatMessage({
                        id: 'mbot.lineFollowerValue',
                        default: 'line follower reading on port [PORT]',
                        description: 'reporter for the raw line follower sensor reading'
                    }),
                    func: 'lineFollowerValue',
                    arguments: {
                        PORT: {
                            type: ArgumentType.NUMBER,
                            defaultValue: DEFAULT_LINE_FOLLOWER_PORT
                        }
                    }
                },
                {
                    opcode: 'isLineFollowerOnBlack',
                    blockType: BlockType.BOOLEAN,
                    text: formatMessage({
                        id: 'mbot.isLineFollowerOnBlack',
                        default: '[SIDE] line follower on black on port [PORT]?',
                        description: 'boolean reporter for one line follower sensor'
                    }),
                    func: 'isLineFollowerOnBlack',
                    arguments: {
                        SIDE: {
                            type: ArgumentType.STRING,
                            menu: 'turnMenu',
                            defaultValue: 'left'
                        },
                        PORT: {
                            type: ArgumentType.NUMBER,
                            defaultValue: DEFAULT_LINE_FOLLOWER_PORT
                        }
                    }
                },
                {
                    opcode: 'isButtonPressed',
                    blockType: BlockType.BOOLEAN,
                    text: formatMessage({
                        id: 'mbot.isButtonPressed',
                        default: 'onboard button pressed?',
                        description: 'boolean reporter for the onboard pushbutton'
                    }),
                    func: 'isButtonPressed'
                }
            ],
            menus: {
                directionMenu: {
                    acceptReporters: true,
                    items: [
                        {
                            text: formatMessage({
                                id: 'mbot.menu.direction.forward',
                                default: 'forward',
                                description: 'label for forward direction'
                            }),
                            value: 'forward'
                        },
                        {
                            text: formatMessage({
                                id: 'mbot.menu.direction.backward',
                                default: 'backward',
                                description: 'label for backward direction'
                            }),
                            value: 'backward'
                        }
                    ]
                },
                turnMenu: {
                    acceptReporters: true,
                    items: [
                        {
                            text: formatMessage({
                                id: 'mbot.menu.turn.left',
                                default: 'left',
                                description: 'label for turning left'
                            }),
                            value: 'left'
                        },
                        {
                            text: formatMessage({
                                id: 'mbot.menu.turn.right',
                                default: 'right',
                                description: 'label for turning right'
                            }),
                            value: 'right'
                        }
                    ]
                },
                ledMenu: {
                    acceptReporters: true,
                    items: [
                        {
                            text: formatMessage({
                                id: 'mbot.menu.led.all',
                                default: 'all',
                                description: 'label for both onboard LEDs'
                            }),
                            value: 'all'
                        },
                        {
                            text: formatMessage({
                                id: 'mbot.menu.led.left',
                                default: 'left',
                                description: 'label for the left onboard LED'
                            }),
                            value: 'left'
                        },
                        {
                            text: formatMessage({
                                id: 'mbot.menu.led.right',
                                default: 'right',
                                description: 'label for the right onboard LED'
                            }),
                            value: 'right'
                        }
                    ]
                }
            }
        };
    }

    connect () {
        this.transport.scan();
    }

    disconnect () {
        this.transport.disconnect();
    }

    isConnected () {
        return this.transport.isConnected();
    }

    lastConnectionError () {
        return this.transport.lastError;
    }

    move (args) {
        const speed = Cast.toNumber(args.SPEED);
        const signedSpeed = args.DIRECTION === 'backward' ? -speed : speed;
        return this._driveTimed(signedSpeed, signedSpeed, args.SECONDS);
    }

    turn (args) {
        const speed = Cast.toNumber(args.SPEED);
        const turningRight = args.DIRECTION === 'right';
        const left = turningRight ? speed : -speed;
        const right = turningRight ? -speed : speed;
        return this._driveTimed(left, right, args.SECONDS);
    }

    setMotors (args) {
        this._send(mbotMoveFrame(Cast.toNumber(args.LEFT), Cast.toNumber(args.RIGHT)));
    }

    stop () {
        this._send(mbotStopFrame());
    }

    setLed (args) {
        const led = LED_TARGET_TO_CONSTANT[args.LED] ?? RGB_LED_ALL;
        this._send(mbotRgbLedFrame(
            led, Cast.toNumber(args.RED), Cast.toNumber(args.GREEN), Cast.toNumber(args.BLUE)
        ));
    }

    playTone (args) {
        this._send(mbotToneFrame(Cast.toNumber(args.FREQUENCY), Cast.toNumber(args.DURATION)));
    }

    stopTone () {
        this._send(mbotToneOffFrame());
    }

    ultrasonicDistance (args) {
        return this._request(
            mbotUltrasonicRequestFrame(Cast.toNumber(args.PORT)),
            bytes => calibrateUltrasonicCm(parseFloatResponse(bytes)),
            0
        );
    }

    lineFollowerValue (args) {
        return this._request(
            mbotLineFollowerRequestFrame(Cast.toNumber(args.PORT)), parseFloatResponse, 0
        );
    }

    isLineFollowerOnBlack (args) {
        const mask = SIDE_TO_LINE_FOLLOWER_MASK[args.SIDE] ?? LINE_FOLLOWER_LEFT_MASK;
        return this._request(
            mbotLineFollowerRequestFrame(Cast.toNumber(args.PORT)),
            bytes => isLineFollowerSideOnBlack(parseFloatResponse(bytes), mask),
            false
        );
    }

    isButtonPressed () {
        return this._request(mbotButtonRequestFrame(), parseButtonPressedResponse, false);
    }

    /**
     * Drives both wheels, then auto-stops after the given duration. The mBot's
     * classic firmware has no motion-completion feedback (unlike e.g. iRobot
     * Root), so open-loop timing is the only option — the block itself waits
     * out the duration before resolving, so sequential drive blocks in a
     * script run one after another rather than overlapping.
     * @param {number} leftSpeed - left wheel speed, -255 to 255.
     * @param {number} rightSpeed - right wheel speed, -255 to 255.
     * @param {number} seconds - how long to drive before stopping.
     * @returns {Promise} - resolves once the stop command has been sent.
     */
    _driveTimed (leftSpeed, rightSpeed, seconds) {
        const durationMs = Math.max(0, Cast.toNumber(seconds)) * 1000;
        this._send(mbotMoveFrame(leftSpeed, rightSpeed));
        return new Promise(resolve => {
            setTimeout(() => {
                this._send(mbotStopFrame());
                resolve();
            }, durationMs);
        });
    }

    /**
     * Fire-and-forget write: a stalled BLE write promise (Scratch Link/Scrub
     * can leave one pending after the peripheral already accepted the bytes)
     * shouldn't hang the calling block's script forever.
     * @param {number[]} frame - the command frame bytes.
     */
    _send (frame) {
        try {
            const pendingWrite = this.transport.write(frame);
            if (pendingWrite && typeof pendingWrite.catch === 'function') {
                pendingWrite.catch(error => this.transport.setError(error));
            }
        } catch (error) {
            this.transport.setError(error);
        }
    }

    /**
     * Sends a sensor GET request and decodes its response, falling back to
     * a default value (rather than leaving a Scratch reporter block blank
     * or throwing mid-script) if the mBot doesn't answer in time — see
     * MBotTransport#request in mbot-ble.js for the timeout itself.
     * @param {number[]} frame - a GET request frame from mbot-protocol.js.
     * @param {function(number[]): *} parseResponse - the matching parser.
     * @param {*} fallbackValue - value to report if the request fails.
     * @returns {Promise<*>} - the parsed sensor value, or fallbackValue.
     */
    _request (frame, parseResponse, fallbackValue) {
        return this.transport.request(frame)
            .then(bytes => parseResponse(bytes))
            .catch(error => {
                this.transport.setError(error);
                return fallbackValue;
            });
    }
}

export {ExtensionBlocks as default, ExtensionBlocks as blockClass};
