/**
 * Builds Makeblock's `0xFF 0x55` mBot command frames — pure byte-building
 * logic, no Bluetooth/Scratch dependency, so it's unit-testable on its own.
 *
 * The motor/joystick part of this is a byte-for-byte port of code_rover_bot's
 * `lib/logic/mbot_protocol.dart` (the Flutter app this extension's sibling
 * project drives the same mBot from) — not a re-derivation. That file's
 * own header explains why the exact bytes matter and where they came from:
 *
 * Byte layout cross-checked against two independent sources rather than
 * trusted from memory, since a wrong device/action/port byte is a
 * silent-failure bug that's hard to debug over BLE:
 * - the official firmware, Makeblock-official/Makeblock-Libraries'
 *   `mbot_firmware.ino` (`parseData`/`runModule`/`readSensor`): frame is
 *   `0xFF 0x55 <len> <idx> <action> <device> <port> <data...>`,
 *   action RUN = 0x02, action GET = 0x01, device MOTOR = 0x0A,
 *   device JOYSTICK = 0x05, M1 port = 0x09 / M2 port = 0x0A
 *   (Makeblock-Libraries' `MePort.h`).
 * - the community client xeecos/python-for-mbot's `mBot.py`
 *   (`doMotor`/`doMove`), which independently produces the same motor bytes
 *   and revealed that the left motor's speed must be sign-flipped relative
 *   to the right (it's mounted mirrored on the chassis) for both wheels to
 *   agree on "forward".
 *
 * The RGB LED / buzzer / ultrasonic / line-follower / onboard-button frames
 * added later are read directly from `mbot_firmware.ino`'s `runModule()`
 * and `readSensor()` switch statements (device ids RGBLED=8, TONE=34,
 * ULTRASONIC_SENSOR=1, LINEFOLLOWER=17, BUTTON_INNER=35, and the `analogs[]`
 * pin table confirming BUTTON_INNER's fixed port=7 maps to pin A7, the
 * classic mBot's onboard-button pin) — not from Makeblock's own mBlock app,
 * which is GPLv2 and intentionally not used as a source here. Unlike the
 * motor/joystick frames, these have only been checked against the firmware
 * source, not yet against a second independent implementation or real
 * hardware — flagged per-function below.
 */

const FRAME_START_1 = 0xFF;
const FRAME_START_2 = 0x55;
const DEFAULT_IDX = 0x00;

const ACTION_RUN = 0x02;
const ACTION_GET = 0x01;

const DEVICE_ULTRASONIC = 0x01;
const DEVICE_JOYSTICK = 0x05;
const DEVICE_RGBLED = 0x08;
const DEVICE_MOTOR = 0x0A;
const DEVICE_LINEFOLLOWER = 0x11;
const DEVICE_TONE = 0x22;
const DEVICE_BUTTON_INNER = 0x23;

/**
 * Single-motor port ids for {@link mbotMotorFrame} (used by the calibration
 * screen to test one wheel at a time). {@link mbotMoveFrame} below is what
 * normal driving uses, since it sets both motors in one frame.
 */
const PORT_M1 = 0x09;
const PORT_M2 = 0x0A;

/**
 * The onboard RGB LEDs and onboard pushbutton aren't wired to a numbered
 * expansion port — the firmware still expects frame bytes as if they were,
 * using fixed values ("led on board" = port 7 / slot 2 in mBot.s2e; the
 * onboard button's port argument of 7 indexes `analogs[7]` = pin A7).
 */
const ONBOARD_PORT = 0x07;
const ONBOARD_LED_SLOT = 0x02;

const RGB_LED_ALL = 0x00;
const RGB_LED_RIGHT = 0x01;
const RGB_LED_LEFT = 0x02;

const MAX_MOTOR_SPEED = 255;

const clampSpeed = speed => {
    if (speed > MAX_MOTOR_SPEED) return MAX_MOTOR_SPEED;
    if (speed < -MAX_MOTOR_SPEED) return -MAX_MOTOR_SPEED;
    return speed;
};

const clampByte = value => Math.max(0, Math.min(255, Math.round(value)));

/**
 * Little-endian signed 16-bit encoding, matching the firmware's byte union
 * and python-for-mbot's `struct.pack("h", ...)` (native byte order, i.e.
 * little-endian on the boards these targets).
 * @param {number} value - signed value already clamped to fit in 16 bits.
 * @returns {number[]} - two bytes, low byte first.
 */
const int16LE = value => {
    const bits = value & 0xFFFF;
    return [bits & 0xFF, (bits >> 8) & 0xFF];
};

/**
 * Assembles a full frame from its body (everything after the length byte)
 * so the length byte itself is always derived, never hand-counted —
 * hand-counting it separately is exactly the kind of off-by-one that stays
 * silently wrong until it's debugged live over BLE.
 * @param {number[]} body - idx, action, device, then device-specific bytes.
 * @returns {number[]} - the complete frame including the 0xFF 0x55 header.
 */
const buildFrame = body => [FRAME_START_1, FRAME_START_2, body.length, ...body];

/**
 * Drives both wheel motors in a single frame (device JOYSTICK, 0x05) so
 * they start together — matters for open-loop timing, where even a small
 * gap between two separate single-motor commands would make the rover
 * veer. leftSpeed/rightSpeed are each clamped to +/-255; positive drives
 * that wheel forward.
 * @param {number} leftSpeed - left wheel speed, -255 to 255.
 * @param {number} rightSpeed - right wheel speed, -255 to 255.
 * @returns {number[]} - the command frame bytes.
 */
const mbotMoveFrame = (leftSpeed, rightSpeed) => {
    const left = clampSpeed(leftSpeed);
    const right = clampSpeed(rightSpeed);
    return buildFrame([
        DEFAULT_IDX, ACTION_RUN, DEVICE_JOYSTICK,
        ...int16LE(-left),
        ...int16LE(right)
    ]);
};

const mbotStopFrame = () => mbotMoveFrame(0, 0);

/**
 * Single-motor command (device MOTOR, 0x0A) for PORT_M1/PORT_M2 — only
 * used by calibration/testing one wheel at a time; normal driving always
 * goes through mbotMoveFrame.
 * @param {number} port - PORT_M1 or PORT_M2.
 * @param {number} speed - motor speed, -255 to 255.
 * @returns {number[]} - the command frame bytes.
 */
const mbotMotorFrame = (port, speed) => buildFrame([
    DEFAULT_IDX, ACTION_RUN, DEVICE_MOTOR, port,
    ...int16LE(clampSpeed(speed))
]);

/**
 * Sets the onboard RGB LEDs (device RGBLED, 0x08). `led` selects which
 * physical LED: RGB_LED_ALL/RGB_LED_LEFT/RGB_LED_RIGHT.
 * NOT yet verified against real hardware or a second source — only
 * against `mbot_firmware.ino`'s `runModule()` RGBLED case.
 * @param {number} led - RGB_LED_ALL, RGB_LED_LEFT, or RGB_LED_RIGHT.
 * @param {number} red - 0-255.
 * @param {number} green - 0-255.
 * @param {number} blue - 0-255.
 * @returns {number[]} - the command frame bytes.
 */
const mbotRgbLedFrame = (led, red, green, blue) => buildFrame([
    DEFAULT_IDX, ACTION_RUN, DEVICE_RGBLED,
    ONBOARD_PORT, ONBOARD_LED_SLOT, led,
    clampByte(red), clampByte(green), clampByte(blue)
]);

/**
 * Plays a tone on the onboard buzzer (device TONE, 0x22). A frequency of 0
 * stops any currently playing tone, matching the firmware's `noTone()`
 * branch. NOT yet verified against real hardware or a second source — only
 * against `mbot_firmware.ino`'s `runModule()` TONE case.
 * @param {number} frequencyHz - tone frequency in Hz, or 0 to stop.
 * @param {number} durationMs - how long the firmware should sound the tone.
 * @returns {number[]} - the command frame bytes.
 */
const mbotToneFrame = (frequencyHz, durationMs) => buildFrame([
    DEFAULT_IDX, ACTION_RUN, DEVICE_TONE,
    ...int16LE(Math.max(0, Math.round(frequencyHz))),
    ...int16LE(Math.max(0, Math.round(durationMs)))
]);

const mbotToneOffFrame = () => mbotToneFrame(0, 0);

/**
 * Requests an ultrasonic distance reading (device ULTRASONIC_SENSOR, 0x01).
 * Response is a headered float — see {@link parseFloatResponse}'s doc for
 * why that's true despite the reference firmware source suggesting
 * otherwise for this specific device.
 * @param {number} port - the port the ultrasonic sensor is plugged into.
 * @returns {number[]} - the request frame bytes.
 */
const mbotUltrasonicRequestFrame = port => buildFrame([
    DEFAULT_IDX, ACTION_GET, DEVICE_ULTRASONIC, port
]);

/**
 * Requests a line-follower reading (device LINEFOLLOWER, 0x11).
 * Response is a headered float — see {@link parseFloatResponse}.
 * @param {number} port - the port the line-follower sensor is plugged into.
 * @returns {number[]} - the request frame bytes.
 */
const mbotLineFollowerRequestFrame = port => buildFrame([
    DEFAULT_IDX, ACTION_GET, DEVICE_LINEFOLLOWER, port
]);

/**
 * Requests the onboard pushbutton's state (device BUTTON_INNER, 0x23).
 * The firmware's actual semantics are an XOR, `s ^ currentPressed`, of the
 * state byte you send against its live reading — sending `s=0` (asking
 * about "pressed") makes that just `currentPressed` directly: 1 = pressed,
 * 0 = released (see {@link parseButtonPressedResponse}; confirmed live —
 * an earlier version of this had the comparison backwards). Port is fixed
 * at 7, which the firmware looks up in its `analogs[]` table as pin A7 —
 * the classic mBot's onboard-button pin.
 * @returns {number[]} - the request frame bytes.
 */
const mbotButtonRequestFrame = () => buildFrame([
    DEFAULT_IDX, ACTION_GET, DEVICE_BUTTON_INNER, ONBOARD_PORT, 0x00
]);

/**
 * Decodes a firmware float32 response value: 1 tag byte (2 = float) then
 * 4 little-endian IEEE-754 bytes, matching `sendFloat()` in the firmware.
 * @param {number[]} bytes - exactly the tag byte followed by 4 value bytes.
 * @returns {number} - the decoded float.
 */
const decodeFloatValue = bytes => {
    const view = new DataView(new Uint8Array(bytes.slice(1, 5)).buffer);
    return view.getFloat32(0, true);
};

/**
 * Parses a headered float response (`0xFF 0x55 <idx>` then the tagged
 * value) — used for both the ultrasonic sensor and the line-follower.
 *
 * `mbot_firmware.ino`'s source has a special case skipping this header for
 * the ultrasonic sensor specifically (`if (device != ULTRASONIC_SENSOR)`
 * around `writeHead()` in `parseData()`) — that does NOT hold on the actual
 * firmware Bilgin's mBot runs, confirmed live: a real distance request
 * decoded as garbage (~1.8e-40) until the header was accounted for here
 * too. Trusting the hardware over that firmware snapshot, which is
 * apparently stale or from a different revision.
 * @param {number[]} bytes - the raw notification payload.
 * @returns {number} - the decoded float value.
 */
const parseFloatResponse = bytes => decodeFloatValue(bytes.slice(3));

/**
 * Parses the onboard button's response to {@link mbotButtonRequestFrame}:
 * 1 = pressed, 0 = released.
 * @param {number[]} bytes - the raw notification payload, `0xFF 0x55 <idx>` then a 1-byte value.
 * @returns {boolean} - true if the button is currently pressed.
 */
const parseButtonPressedResponse = bytes => bytes[4] === 1;

/**
 * Corrects the ultrasonic sensor's raw `distanceCm()` reading, which runs
 * consistently ~20-25% low on this specific mBot. Fitted (least squares)
 * from three live tape-measure readings against the raw sensor value:
 * (10cm, 8.39), (15cm, 12.3), (26cm, 20.8) — residuals under 0.02cm across
 * that whole range, so this is a real per-unit calibration constant, not
 * noise. It's specific to this physical sensor/board, not a general mBot
 * property — a different unit could need a different constant.
 * @param {number} rawCm - the value decoded from the firmware's response.
 * @returns {number} - the corrected distance in centimeters.
 */
const calibrateUltrasonicCm = rawCm => (1.2901 * rawCm) - 0.8417;

/**
 * Bit masks for {@link isLineFollowerSideOnBlack} against the raw value
 * from {@link mbotLineFollowerRequestFrame}'s response (`dRead1()*2 +
 * dRead2()` per the firmware). These weights match mBot.s2e's own
 * "leftRight" menu constants (leftSide=2, rightSide=1) exactly, and were
 * cross-checked live: a light surface read 3 (both bits set, both sensors
 * HIGH) and a dark surface read 0 (both LOW) — so HIGH/1 = light,
 * LOW/0 = dark, for each sensor independently.
 */
const LINE_FOLLOWER_LEFT_MASK = 2;
const LINE_FOLLOWER_RIGHT_MASK = 1;

/**
 * @param {number} rawValue - the decoded line-follower value (0-3).
 * @param {number} mask - LINE_FOLLOWER_LEFT_MASK or LINE_FOLLOWER_RIGHT_MASK.
 * @returns {boolean} - true if that sensor currently reads a dark surface.
 */
const isLineFollowerSideOnBlack = (rawValue, mask) => (rawValue & mask) === 0;

module.exports = {
    PORT_M1,
    PORT_M2,
    MAX_MOTOR_SPEED,
    RGB_LED_ALL,
    RGB_LED_LEFT,
    RGB_LED_RIGHT,
    mbotMoveFrame,
    mbotStopFrame,
    mbotMotorFrame,
    mbotRgbLedFrame,
    mbotToneFrame,
    mbotToneOffFrame,
    mbotUltrasonicRequestFrame,
    mbotLineFollowerRequestFrame,
    mbotButtonRequestFrame,
    parseFloatResponse,
    calibrateUltrasonicCm,
    LINE_FOLLOWER_LEFT_MASK,
    LINE_FOLLOWER_RIGHT_MASK,
    isLineFollowerSideOnBlack,
    parseButtonPressedResponse
};
