/**
 * This is an extension for Xcratch.
 */

import iconURL from './entry-icon.png';
import insetIconURL from './inset-icon.svg';
import translations from './translations.json';
import {version as packageVersion} from '../../../../../../package.json';

/**
 * Formatter to translate the messages in this extension.
 * This will be replaced which is used in the React component.
 * @param {object} messageData - data for format-message
 * @returns {string} - translated message for the current locale
 */
let formatMessage = messageData => messageData.defaultMessage;

const version = `v${packageVersion}`;

const entry = {
    get name () {
        return formatMessage({
            id: 'mbot.entry.name',
            defaultMessage: 'mBot',
            description: 'name of the extension'
        });
    },
    extensionId: 'mbot',
    extensionURL: 'https://bilgin.github.io/xcx-mbot/dist/mbot.mjs',
    collaborator: 'bilgin',
    iconURL: iconURL,
    insetIconURL: insetIconURL,
    get description () {
        return `${formatMessage({
            defaultMessage: 'Drive a Makeblock mBot over Bluetooth',
            description: 'Description for this extension',
            id: 'mbot.entry.description'
        })} (${version})`;
    },
    tags: ['robotics', 'bluetooth', 'hardware'],
    featured: true,
    disabled: false,
    bluetoothRequired: true,
    internetConnectionRequired: false,
    helpLink: 'https://github.com/bilgin/k5_math',
    setFormatMessage: formatter => {
        formatMessage = formatter;
    },
    translationMap: translations
};

export {entry}; // loadable-extension needs this line.
export default entry;
