import ScratchLinkBLE from '../../io/ble';
import WebBLE from '../../io/ble-web';

/**
 * "Makeblock_LE"-advertised module used by the classic mBot: service 0xFFE1,
 * write characteristic 0xFFE3. Same UUIDs code_rover_bot's Flutter app
 * discovers at connect time (`services/mbot_service.dart`), expanded here
 * from the 16-bit alias to the full UUID Web Bluetooth's `requestDevice`
 * expects for a `services` filter.
 *
 * The notify characteristic 0xFFE2 (needed for sensor GET requests —
 * mbotUltrasonicRequestFrame etc. in mbot-protocol.js) was never exercised
 * by the Flutter app, which only ever wrote drive commands. Confirmed
 * instead against an independent open-source Web Bluetooth mBot client
 * (tatiang/mbot-vr's BluetoothLeTransport.ts), which documents the same
 * ffe1 service / ffe2 notify / ffe3 write layout for this exact BLE module —
 * not yet confirmed against Bilgin's own physical mBot.
 */
const MBOT_SERVICE = '0000ffe1-0000-1000-8000-00805f9b34fb';
const MBOT_NOTIFY_CHARACTERISTIC = '0000ffe2-0000-1000-8000-00805f9b34fb';
const MBOT_WRITE_CHARACTERISTIC = '0000ffe3-0000-1000-8000-00805f9b34fb';

const SENSOR_RESPONSE_TIMEOUT_MS = 1000;

const MBOT_DISCOVERY_OPTIONS = {
    filters: [{namePrefix: 'Makeblock'}],
    optionalServices: [MBOT_SERVICE]
};

const supportsWebBluetooth = (navigatorObject = typeof navigator === 'undefined' ? null : navigator) =>
    Boolean(navigatorObject && navigatorObject.bluetooth &&
        typeof navigatorObject.bluetooth.requestDevice === 'function');

/**
 * Prefer Web Bluetooth (works in Chrome on the target Android tablet)
 * and only fall back to Scratch Link's BLE class when it's unavailable —
 * same selection Xcratch's own reference extensions use, so a desktop
 * build of this extension keeps working without a code change.
 */
const selectBLEAdapter = navigatorObject => (supportsWebBluetooth(navigatorObject) ? WebBLE : ScratchLinkBLE);

// Scratch Link's BLE class relays writes over a JSON-RPC socket, so a raw
// byte array can't cross it as-is — base64 works for both that path and
// WebBLE (which decodes it right back to bytes), so always send this way.
const bytesToBase64 = bytes => {
    let binary = '';
    for (const value of bytes) binary += String.fromCharCode(value);
    return btoa(binary);
};

const base64ToBytes = base64 => Array.from(atob(base64), char => char.charCodeAt(0));

/**
 * Owns the BLE session lifecycle for one mBot connection: scanning,
 * connect/disconnect, and writing pre-built command frames (see
 * mbot-protocol.js). There's no RootProtocol-style packet/CRC layer here —
 * mBot's `0xFF 0x55` frames are simpler and already fully built by the
 * caller, so this class only moves bytes.
 */
class MBotTransport {
    constructor (runtime, extensionId) {
        this.runtime = runtime;
        this.extensionId = extensionId;
        this.ble = null;
        this.lastError = '';

        /**
         * At most one outstanding sensor GET request at a time — {@link
         * request} resolves it from the next notification that arrives, or
         * times out. mBot's firmware answers whatever GET it most recently
         * received, so there's no per-request id to demultiplex several in
         * flight; Scratch reporter blocks call this sequentially anyway.
         * @type {?{resolve: Function, reject: Function, timeout: number}}
         */
        this._pendingRequest = null;

        // Lets Scratch's built-in "Connect a device" dialog find and drive
        // this extension the same way it drives any first-party peripheral.
        this.runtime.registerPeripheralExtension(extensionId, this);
        this.onConnect = this.onConnect.bind(this);
        this.reset = this.reset.bind(this);
        this._registerRuntimeDiagnostics();
    }

    scan () {
        if (this.ble) this.ble.disconnect();
        this.lastError = '';
        const BLEAdapter = selectBLEAdapter();
        try {
            this.ble = new BLEAdapter(
                this.runtime, this.extensionId, MBOT_DISCOVERY_OPTIONS, this.onConnect, this.reset
            );
        } catch (error) {
            this.setError(error);
            throw error;
        }
    }

    connect (peripheralId) {
        if (this.ble) this.ble.connectPeripheral(peripheralId);
    }

    onConnect () {
        // Subscribes so sensor GET requests (mbot-protocol.js's
        // mbotUltrasonicRequestFrame etc.) have somewhere to receive their
        // response. If this particular mBot's BLE module doesn't expose
        // ffe2, this rejects and driving still works fine — only the
        // sensor reporter blocks would time out.
        this.ble.startNotifications(MBOT_SERVICE, MBOT_NOTIFY_CHARACTERISTIC, message => {
            this._handleNotification(base64ToBytes(message));
        }).catch(error => this.setError(error));
    }

    write (bytes) {
        if (!this.isConnected()) return Promise.reject(new Error('Not connected to an mBot.'));
        return this.ble.write(MBOT_SERVICE, MBOT_WRITE_CHARACTERISTIC, bytesToBase64(bytes), 'base64', false)
            .catch(error => {
                this.setError(error);
                throw error;
            });
    }

    /**
     * Sends a sensor GET request frame and resolves with the raw response
     * bytes from the next BLE notification — the caller (index.js) decodes
     * them with the matching mbot-protocol.js parser. Rejects if nothing
     * arrives within {@link SENSOR_RESPONSE_TIMEOUT_MS}.
     * @param {number[]} bytes - a GET request frame.
     * @returns {Promise<number[]>} - the raw notification payload.
     */
    request (bytes) {
        if (!this.isConnected()) return Promise.reject(new Error('Not connected to an mBot.'));
        if (this._pendingRequest) this._pendingRequest.reject(new Error('Superseded by a newer request.'));

        return new Promise((resolve, reject) => {
            const timeout = setTimeout(() => {
                if (this._pendingRequest && this._pendingRequest.timeout === timeout) {
                    this._pendingRequest = null;
                    reject(new Error('mBot did not respond in time.'));
                }
            }, SENSOR_RESPONSE_TIMEOUT_MS);
            this._pendingRequest = {resolve, reject, timeout};

            this.write(bytes).catch(error => {
                if (this._pendingRequest && this._pendingRequest.timeout === timeout) {
                    clearTimeout(timeout);
                    this._pendingRequest = null;
                    reject(error);
                }
            });
        });
    }

    _handleNotification (bytes) {
        if (!this._pendingRequest) return;
        clearTimeout(this._pendingRequest.timeout);
        const {resolve} = this._pendingRequest;
        this._pendingRequest = null;
        resolve(bytes);
    }

    disconnect () {
        if (this.ble) this.ble.disconnect();
        this.reset();
    }

    isConnected () {
        return Boolean(this.ble && this.ble.isConnected());
    }

    reset () {
        this.lastError = '';
        if (this._pendingRequest) {
            this._pendingRequest.reject(new Error('Disconnected from the mBot.'));
            this._pendingRequest = null;
        }
    }

    setError (error) {
        this.lastError = error && error.message ? error.message : String(error || 'BLE error');
    }

    _registerRuntimeDiagnostics () {
        if (!this.runtime.on) return;
        const RuntimeClass = this.runtime.constructor;
        this.runtime.on(RuntimeClass.PERIPHERAL_CONNECTED, () => {
            this.lastError = '';
        });
        this.runtime.on(RuntimeClass.PERIPHERAL_REQUEST_ERROR, details => {
            if (!details || !details.extensionId || details.extensionId === this.extensionId) {
                this.lastError = 'Failed to request a BLE connection.';
            }
        });
        this.runtime.on(RuntimeClass.PERIPHERAL_SCAN_TIMEOUT, () => {
            this.lastError = 'No mBot found nearby — make sure it\'s powered on.';
        });
        this.runtime.on(RuntimeClass.PERIPHERAL_CONNECTION_LOST_ERROR, details => {
            if (!details || !details.extensionId || details.extensionId === this.extensionId) {
                this.lastError = 'Lost connection to the mBot.';
            }
        });
    }
}

export {
    MBOT_DISCOVERY_OPTIONS,
    MBOT_SERVICE,
    MBOT_NOTIFY_CHARACTERISTIC,
    MBOT_WRITE_CHARACTERISTIC,
    MBotTransport,
    selectBLEAdapter,
    supportsWebBluetooth
};
